    /// Adds a story at the end of Next sprint, open, its title focused, in
    /// the mode last picked: however a story is added, it goes there, as
    /// the PlanningScope's creating says.
    pub fn new_story(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.new_story_at(None, window, cx);
    }

    /// Adds a story to Next sprint at place `at`, or its end.
    fn new_story_at(&mut self, at: Option<usize>, window: &mut Window, cx: &mut Context<Self>) {
        let section = Section::Next;
        self.close_story(window, cx);
        let story = Story::new(String::new(), String::new(), last_mode(), &self.project_dir);
        let name = story.name.clone();
        let stories = &mut self.sections[section_ix(section)];
        let at = at.unwrap_or(stories.len()).min(stories.len());
        stories.insert(at, story);
        self.save_story_named(&name, cx);
        self.save_order(cx);
        self.open_story(&name, window, cx);
    }

    /// Adds a story of `mode` holding `prompt` at the end of `section`.
    pub fn add_story(
        &mut self,
        section: Section,
        title: String,
        prompt: String,
        mode: SendMode,
        cx: &mut Context<Self>,
    ) {
        let story = Story::new(title, prompt, mode, &self.project_dir);
        let name = story.name.clone();
        self.sections[section_ix(section)].push(story);
        self.save_story_named(&name, cx);
        self.save_order(cx);
        cx.notify();
    }

