/// The anchor a markdown heading is linked by: its words, lowercase, joined
/// by dashes, with only letters, digits, dashes, and underscores kept.
fn heading_anchor(heading: &str) -> String {
    heading
        .trim()
        .to_lowercase()
        .chars()
        .filter_map(|c| match c {
            ' ' => Some('-'),
            c if c.is_alphanumeric() || c == '-' || c == '_' => Some(c),
            _ => None,
        })
        .collect()
}

/// Whether `link`, a citation's, points at a heading that exists in the
/// compiled reference of the project at `project_dir`; why not where it
/// doesn't.
pub fn check_link(link: &str, project_dir: &Path) -> Result<(), String> {
    let reference = crate::hidden_anchor::reference_root(project_dir);
    let (path, anchor) = link.split_once('#').unwrap_or((link, ""));
    let path = path.trim_start_matches("./");
    if !path.starts_with(reference) {
        return Err(format!("it isn't in the compiled reference, {reference}"));
    }
    let Ok(text) = std::fs::read_to_string(project_dir.join(path)) else {
        return Err("its page doesn't exist".into());
    };
    if anchor.is_empty() {
        return Ok(());
    }
    let found = text
        .lines()
        .filter_map(|line| line.trim_start().strip_prefix('#'))
        .map(|heading| heading_anchor(heading.trim_start_matches('#')))
        .any(|heading| heading == anchor);
    if found {
        Ok(())
    } else {
        Err(format!("its page has no heading #{anchor}"))
    }
}

/// A task the agent proposes, as the PlanningScope's proposals say: its
/// title, prompt, and mode, and where it goes, a new story or a step of an
/// existing one, waiting to be accepted, edited, or rejected.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Proposal {
    /// What it is known by while it waits.
    pub id: String,
    pub title: String,
    pub prompt: String,
    /// Its mode, as a `suspense-story` block names it.
    pub mode: String,
    /// The story it is to be added to, by name; none for a new story.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub target: Option<String>,
    /// Why it is a new story though another was named, shown muted.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
    /// The story the drafting run was asked about, beneath which it shows.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub about: Option<String>,
    /// The spec elements it touches, as found.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub spec: Vec<Citation>,
    /// The citations dropped as it arrived, and why, shown muted.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub dropped: Vec<String>,
}

impl Proposal {
    pub fn mode(&self) -> SendMode {
        mode_of_slug(&self.mode).unwrap_or(SendMode::Both)
    }

    /// What a new story made from it is titled: its title, or its prompt's
    /// first line.
    fn story_title(&self) -> String {
        if self.title.trim().is_empty() {
            self.prompt
                .lines()
                .next()
                .unwrap_or_default()
                .trim()
                .to_string()
        } else {
            self.title.trim().to_string()
        }
    }
}

/// A fresh id for a proposal.
fn proposal_id() -> String {
    HiddenAnchor::random_name().replacen("Prompt_", "Proposal_", 1)
}

/// The proposal a `suspense-story` block holds: a line each for its title,
/// mode, and target, `new` or a story's id, then, after a blank line, its
/// prompt. None for a block with neither title nor prompt.
pub fn parse_story_block(body: &str) -> Option<Proposal> {
    let mut proposal = Proposal {
        id: proposal_id(),
        title: String::new(),
        prompt: String::new(),
        mode: "chain".into(),
        target: None,
        note: None,
        about: None,
        spec: Vec::new(),
        dropped: Vec::new(),
    };
    let mut lines = body.lines();
    let mut prompt: Vec<&str> = Vec::new();
    let mut in_spec = false;
    for line in lines.by_ref() {
        if line.trim().is_empty() {
            break;
        }
        // The spec list: its entries, one per line, each begun with a dash.
        if in_spec && line.trim_start().starts_with(['-', '*']) {
            proposal.spec.extend(Citation::parse(line));
            continue;
        }
        in_spec = false;
        let Some((key, value)) = line.split_once(':') else {
            prompt.push(line);
            break;
        };
        let value = value.trim();
        match key.trim().to_ascii_lowercase().as_str() {
            "title" => proposal.title = value.to_string(),
            "mode" => {
                if let Some(mode) = mode_of_slug(value) {
                    proposal.mode = mode_slug(mode).into();
                }
            }
            "target" => {
                proposal.target = (!value.is_empty() && !value.eq_ignore_ascii_case("new"))
                    .then(|| value.to_string());
            }
            "spec" => {
                in_spec = true;
                proposal.spec.extend(Citation::parse(value));
            }
            "prompt" => {
                if !value.is_empty() {
                    prompt.push(value);
                }
                break;
            }
            _ => {
                prompt.push(line);
                break;
            }
        }
    }
    prompt.extend(lines);
    proposal.prompt = prompt.join("\n").trim().to_string();
    (!proposal.title.trim().is_empty() || !proposal.prompt.is_empty()).then_some(proposal)
}

