pub fn parse_proposals(reply: &str) -> Vec<Proposal> {
    crate::answer_blocks::split(reply)
        .into_iter()
        .filter_map(|part| match part {
            crate::answer_blocks::AnswerPart::Story { proposal, .. } => proposal,
            _ => None,
        })

