static TARGET: std::sync::Mutex<String> = std::sync::Mutex::new(String::new());

/// A compiled reference page in the project at `dir`, with a Sprint
/// heading.
fn reference(dir: &Path) {
    let page = dir.join(".claude/reference/scope/planning");
    std::fs::create_dir_all(&page).unwrap();
    std::fs::write(
        page.join("index.md"),
