    let block = "title: Sprint\nmode: chain\ntarget: new\nspec:\n- .claude/reference/scope/planning/index.md#sprint — how it is sent\n- [Planning](.claude/reference/scope/planning/index.md#planning)\n- No match — a calendar\n\nDo it.";
    let proposal = parse_story_block(block).unwrap();
    assert_eq!(proposal.prompt, "Do it.");
    assert_eq!(proposal.spec.len(), 3);
    assert_eq!(proposal.spec[0].note, "how it is sent");
    assert_eq!(
        proposal.spec[1].link.as_deref(),
        Some(".claude/reference/scope/planning/index.md#planning")
    );
    assert_eq!(proposal.spec[2].link, None);
    assert_eq!(proposal.spec[2].note, "a calendar");
    assert!(
        super::check_link(".claude/reference/scope/planning/index.md#sprint", &dir).is_ok()
    );
    assert!(
        super::check_link(".claude/reference/scope/planning/index.md#nowhere", &dir).is_err()
    );
    assert!(super::check_link(".claude/reference/scope/gone/index.md#sprint", &dir).is_err());
    assert!(super::check_link("spec/planning.pi#sprint", &dir).is_err());
    std::fs::remove_dir_all(&dir).ok();
}

